traces.query:
PREFIX sup: <http://example.org/sapsupport#>

SELECT ?dataType WHERE {
  sup:Column_M_SAVEPOINTS__DURATION sup:dataType ?dataType .
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT ?category WHERE {
  sup:Statement_ALTER_SYSTEM_SAVEPOINT sup:statementCategory ?category .
}

PREFIX sup: <http://example.org/sapsupport#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name WHERE {
  sup:Alert_54 rdfs:label ?name .
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT ?alert ?alertNumber WHERE {
  sup:Article_1977220 sup:addresses ?alert .
  OPTIONAL { ?alert sup:alertNumber ?alertNumber }
}

PREFIX ppms: <http://example.org/ppms#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?component ?label WHERE {
  ppms:PV_HANA_Platform_2_0 ppms:includesComponent ?component .
  OPTIONAL { ?component rdfs:label ?label }
}

PREFIX sup: <http://example.org/sapsupport#>

SELECT ?view ?viewName WHERE {
  ?view sup:hasColumn ?col .
  ?col sup:columnName "FLUSHED_ROWSTORE_SIZE_IN_CRITICAL_PHASE" .
  OPTIONAL { ?view sup:viewName ?viewName }
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT ?columnName WHERE {
  sup:View_M_PASSWORD_POLICY sup:hasColumn ?col .
  ?col sup:columnName ?columnName .
}
ORDER BY ?columnName

PREFIX sup: <http://example.org/sapsupport#>
SELECT ?article ?articleNumber WHERE {
  ?article sup:addresses sup:Alert_55 .
  OPTIONAL { ?article sup:articleNumber ?articleNumber . }
}

PREFIX sup: <http://example.org/sapsupport#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?alert ?alertNumber ?label
WHERE {
  ?alert sup:investigatedWith sup:View_M_DISK_USAGE .
  OPTIONAL { ?alert sup:alertNumber ?alertNumber . }
  OPTIONAL { ?alert rdfs:label ?label . }
}
ORDER BY ?alertNumber

PREFIX sup: <http://example.org/sapsupport#>
SELECT DISTINCT ?article ?articleNumber WHERE {
  ?alert sup:alertNumber 25 .
  ?article sup:mentionsAlert ?alert ;
           sup:articleNumber ?articleNumber .
}

PREFIX ppms: <http://example.org/ppms#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?version ?label
WHERE {
  ?version ppms:versionOf ppms:Product_HANA_Platform .
  OPTIONAL { ?version rdfs:label ?label . }
}
ORDER BY ?version

PREFIX ppms: <http://example.org/ppms#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?sp ?label
WHERE {
  ?sp ppms:supportPackageOf ppms:SC_HANA_DB_2_0 .
  OPTIONAL { ?sp rdfs:label ?label }
}
ORDER BY ?sp

PREFIX sup: <http://example.org/sapsupport#>
SELECT ?view ?viewName WHERE {
  sup:Article_1977207 sup:addresses ?alert .
  ?alert sup:investigatedWith ?view .
  OPTIONAL { ?view sup:viewName ?viewName }
}

PREFIX sup: <http://example.org/sapsupport#>

SELECT ?view ?columnName WHERE {
  sup:Alert_55 sup:investigatedWith ?view .
  ?view sup:hasColumn ?column .
  ?column sup:dataType "TIMESTAMP" ;
          sup:columnName ?columnName .
}

PREFIX sup: <http://example.org/sapsupport#>

SELECT ?view ?viewName
WHERE {
  sup:Alert_2 sup:investigatedWith ?view .
  OPTIONAL { ?view sup:viewName ?viewName . }
}

PREFIX ppms: <http://example.org/ppms#>
SELECT ?line WHERE {
  ppms:PV_HANA_Platform_2_0 ppms:versionOf ?product .
  ?product ppms:inProductLine ?line .
}

PREFIX ppms: <http://example.org/ppms#>

SELECT DISTINCT ?sc ?sp ?sps WHERE {
  ppms:PV_HANA_Platform_2_0 ppms:includesComponent ?sc .
  ?sp ppms:supportPackageOf ?sc .
  OPTIONAL { ?sp ppms:spsNumber ?sps . }
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT DISTINCT ?article ?articleNumber WHERE {
  ?alert sup:investigatedWith sup:View_M_CS_UNLOADS .
  ?article sup:addresses ?alert .
  OPTIONAL { ?article sup:articleNumber ?articleNumber . }
}

PREFIX sup: <http://example.org/sapsupport#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?statement ?label WHERE {
  { sup:View_M_SAVEPOINTS sup:seeAlso ?statement . }
  UNION
  { ?statement sup:seeAlso sup:View_M_SAVEPOINTS . }
  ?statement a sup:SQLStatement ;
             sup:statementCategory "System Management" ;
             rdfs:label ?label .
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT ?number WHERE {
  sup:View_M_LICENSES ^sup:investigatedWith ?alert .
  ?alert sup:alertNumber ?number .
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT (COUNT(DISTINCT ?column) AS ?columnCount)
WHERE {
  ?column sup:columnOf sup:View_M_SAVEPOINTS .
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT (COUNT(DISTINCT ?s) AS ?count)
WHERE {
  ?s a sup:SQLStatement ;
     sup:statementCategory ?cat .
  FILTER(LCASE(STR(?cat)) = "system management")
}

PREFIX sup: <http://example.org/sapsupport#>

SELECT ?view ?viewName (COUNT(?col) AS ?columnCount)
WHERE {
  ?view a sup:MonitoringView ;
        sup:hasColumn ?col .
  OPTIONAL { ?view sup:viewName ?viewName . }
}
GROUP BY ?view ?viewName
ORDER BY DESC(?columnCount)
LIMIT 1

PREFIX sup: <http://example.org/sapsupport#>
SELECT (COUNT(DISTINCT ?alert) AS ?alertCount)
WHERE {
  ?article a sup:KnowledgeArticle ;
           sup:addresses ?alert .
  ?alert a sup:Alert .
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT ?category (COUNT(?stmt) AS ?count)
WHERE {
  ?stmt a sup:SQLStatement ;
        sup:statementCategory ?category .
}
GROUP BY ?category
ORDER BY DESC(?count)
LIMIT 1

PREFIX sup: <http://example.org/sapsupport#>

SELECT ?article ?articleNumber
WHERE {
  ?article a sup:KnowledgeArticle .
  OPTIONAL { ?article sup:articleNumber ?articleNumber . }
  FILTER NOT EXISTS { ?article sup:addresses ?alert . }
}
ORDER BY ?articleNumber

PREFIX sup: <http://example.org/sapsupport#>
SELECT ?alert ?alertNumber WHERE {
  ?alert a sup:Alert .
  OPTIONAL { ?alert sup:alertNumber ?alertNumber }
  FILTER NOT EXISTS { ?alert sup:investigatedWith ?view }
}

PREFIX sup: <http://example.org/sapsupport#>
SELECT DISTINCT ?alert ?alertNumber ?article ?articleNumber WHERE {
  ?article sup:mentionsAlert ?alert .
  FILTER NOT EXISTS { ?article sup:addresses ?alert . }
  OPTIONAL { ?alert sup:alertNumber ?alertNumber . }
  OPTIONAL { ?article sup:articleNumber ?articleNumber . }
}

PREFIX sup: <http://example.org/sapsupport#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?statement ?label
WHERE {
  ?statement a sup:SQLStatement ;
             sup:statementCategory "Transaction Management" .
  OPTIONAL { ?statement rdfs:label ?label . }
  FILTER NOT EXISTS { ?statement sup:seeAlso ?topic . }
}
